<?php
require_once __DIR__.'/../config/app.php';require_admin();$type=trim($_GET['type']??'');$status=trim($_GET['status']??'');$sql='SELECT items.*,users.full_name,users.email FROM items INNER JOIN users ON users.id=items.user_id WHERE 1=1';$params=[];$types='';if(in_array($type,['lost','found'],true)){$sql.=' AND items.type=?';$params[]=&$type;$types.='s';}if(in_array($status,['active','claimed','returned'],true)){$sql.=' AND items.status=?';$params[]=&$status;$types.='s';}$sql.=' ORDER BY items.created_at DESC';$s=mysqli_prepare($conn,$sql);if($types!=='')mysqli_stmt_bind_param($s,$types,...$params);mysqli_stmt_execute($s);$r=mysqli_stmt_get_result($s);
?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Manage Items - UniFind</title><link rel="stylesheet" href="../css/style.css"></head><body><nav class="navbar"><a class="brand" href="dashboard.php">UniFind Admin</a><div class="nav-actions"><a class="btn btn-small btn-secondary" href="dashboard.php">Dashboard</a><a class="btn btn-small" href="../logout.php">Logout</a></div></nav><main class="page-container"><section class="page-heading"><div><span class="eyebrow">System Reports</span><h1>Manage Items</h1><p>Review all lost and found reports submitted by users.</p></div></section><form class="filter-bar compact-filter" method="get"><select name="type"><option value="">All Types</option><option value="lost" <?=$type==='lost'?'selected':''?>>Lost</option><option value="found" <?=$type==='found'?'selected':''?>>Found</option></select><select name="status"><option value="">All Statuses</option><option value="active" <?=$status==='active'?'selected':''?>>Active</option><option value="claimed" <?=$status==='claimed'?'selected':''?>>Claimed</option><option value="returned" <?=$status==='returned'?'selected':''?>>Returned</option></select><button class="btn">Filter</button><a class="btn btn-secondary" href="items.php">Reset</a></form><?php if(mysqli_num_rows($r)):?><section class="item-grid"><?php while($i=mysqli_fetch_assoc($r)):?><article class="item-card"><?php if($i['image']&&is_file(__DIR__.'/../uploads/'.$i['image'])):?><img class="item-image" src="../uploads/<?=e($i['image'])?>" alt=""><?php else:?><div class="item-image placeholder">No Image Available</div><?php endif;?><div class="item-card-body"><div class="card-topline"><span class="status-pill <?=$i['type']==='lost'?'lost-pill':'found-pill'?>"><?=strtoupper(e($i['type']))?></span><span class="status-pill neutral-pill"><?=strtoupper(e($i['status']))?></span></div><h3><?=e($i['item_name'])?></h3><p class="item-description"><?=e($i['description'])?></p><div class="detail-list"><span><strong>Category:</strong> <?=e($i['category'])?></span><span><strong>Location:</strong> <?=e($i['location'])?></span><span><strong>Date:</strong> <?=e($i['item_date'])?></span><span><strong>Reporter:</strong> <?=e($i['full_name'])?> (<?=e($i['email'])?>)</span></div></div></article><?php endwhile;?></section><?php else:?><div class="empty-state"><h3>No items found</h3><p>No reports match the current filters.</p></div><?php endif;?></main><script src="../js/ui-effects.js"></script></body></html>